	protected class ObjectsTreeRenderer : GTreeRenderer, ColorsModified.InTree {
		{
			setHTMLRenderingEnabled(true);
		}

		private bool isOnCurrentPath(TraceObjectValue value) {
			if (value == null) {
				return false;
			}
			return (value.getValue() is TraceObject child && isOnCurrentPath(child));
		}

		private bool isOnCurrentPath(TraceObject @object) {
			TraceObject cur = current.getObject();
			if (cur == null) {
				return false;
			}
			return @object.getCanonicalPath().isAncestor(cur.getCanonicalPath());
		}

		/* @Override */
		public Component getTreeCellRendererComponent(JTree tree, object value, bool selected,
				bool expanded, bool leaf, int row, bool hasFocus) {
			base.getTreeCellRendererComponent(tree, value, selected, expanded, leaf, row,
				hasFocus);
			if (!(value is AbstractNode)) {
				return this;
			}

			AbstractNode node = (AbstractNode) value;
			setForeground(getForegroundFor(tree, node.isModified(), selected));
			setFont(getFont(isOnCurrentPath(node.getValue())));
			return this;
		}

		/* @Override */
		public Color getDiffForeground(JTree tree) {
			return diffColor;
		}

		/* @Override */
		public Color getDiffSelForeground(JTree tree) {
			return diffColorSel;
		}
	}

